import type { ComputedPlacement, BasePlacement } from '@popperjs/core'
import { createPopper } from '@popperjs/core'
import clsx from 'clsx'
import React, {
  useState,
  useRef,
  Children,
  useCallback,
  useEffect,
  useLayoutEffect,
  isValidElement,
  cloneElement,
} from 'react'
import type { PropsWithChildren, ReactElement } from 'react'
import { useId } from '../hooks/useId'
import { applyMaxSize, maxSize } from '../utilities/applyMaxSize'
import createDisposables from '../utilities/createDisposables'
import { getInteractiveChild } from '../utilities/getInteractiveChild'
import { Keys } from '../utilities/keyboard'

const CLOSE_DELAY = 75
const EXIT_DURATION = 100

export interface TooltipProps {
  /**
   * Whether to display an arrow pointing to the target element
   * @default false
   */
  arrow?: boolean
  /**
   * The preferred placement of the tooltip relative to the target element
   * @default 'bottom'
   */
  placement?: ComputedPlacement
  /**
   * The text content to display in the tooltip
   */
  title: string
}

type ArrowStyles = {
  class: { [key in BasePlacement]: string }
  style: {
    [key in BasePlacement]: {
      borderLeftColor?: string
      borderRightColor?: string
      borderTopColor?: string
      borderBottomColor?: string
      marginTop?: string
      marginBottom?: string
      marginLeft?: string
      marginRight?: string
    }
  }
}

export interface InteractiveChildNode extends ChildNode {
  // Optional as not all interactive elements support a 'disabled' attribute
  disabled?: boolean
}

// The arrow points back at the target, so it sits on the tooltip's opposite side
const oppositeSide: { [side: string]: BasePlacement } = {
  top: 'bottom',
  bottom: 'top',
  left: 'right',
  right: 'left',
}

const ARROW_OFFSET = '-11px'

const styles: ArrowStyles = {
  class: {
    top: 'top-0 -translate-y-full',
    bottom: 'bottom-0 translate-y-full',
    left: 'left-0 -mb-1 -translate-x-full',
    right: 'right-0 -mb-1 translate-x-full',
  },
  style: {
    top: {
      borderLeftColor: 'transparent',
      borderRightColor: 'transparent',
      borderTopColor: 'transparent',
      marginTop: ARROW_OFFSET,
    },
    bottom: {
      borderLeftColor: 'transparent',
      borderRightColor: 'transparent',
      borderBottomColor: 'transparent',
      marginBottom: ARROW_OFFSET,
    },
    right: {
      borderRightColor: 'transparent',
      borderBottomColor: 'transparent',
      borderTopColor: 'transparent',
      marginRight: ARROW_OFFSET,
    },
    left: {
      borderBottomColor: 'transparent',
      borderLeftColor: 'transparent',
      borderTopColor: 'transparent',
      marginLeft: ARROW_OFFSET,
    },
  },
}

function Tooltip({
  title,
  children,
  arrow = false,
  placement = 'bottom',
}: PropsWithChildren<TooltipProps>): JSX.Element {
  const [arrowDirection, setArrowDirection] = useState<BasePlacement>('top')
  const [isOpen, setIsOpen] = useState(false)
  const [displayed, setDisplayed] = useState(false)
  const [entering, setEntering] = useState(false)
  const [interactive, setInteractive] = useState<
    InteractiveChildNode | undefined
  >()

  const isTouch = window.matchMedia(
    '(any-hover: none) and (any-pointer: coarse)',
  ).matches

  const tooltipRef = useRef<HTMLDivElement | null>(null)
  const arrowRef = useRef<HTMLDivElement | null>(null)
  const hoverableRef = useRef<HTMLDivElement | null>(null)

  const id = `coconut-tooltip-${useId()}`

  const open = useCallback(() => setIsOpen(true), [])

  const close = useCallback(() => setIsOpen(false), [])

  useEffect(() => {
    if (!children) {
      return
    }

    setInteractive(getInteractiveChild(hoverableRef.current))
  }, [children])

  useLayoutEffect(() => {
    const disposables = createDisposables()

    if (isOpen) {
      setDisplayed(true)
      setEntering(true)
    } else {
      disposables.setTimeout(() => setEntering(false), CLOSE_DELAY)
      disposables.setTimeout(
        () => setDisplayed(false),
        CLOSE_DELAY + EXIT_DURATION,
      )
    }

    return () => disposables.dispose()
  }, [isOpen])

  useLayoutEffect(() => {
    const hoverable = hoverableRef.current
    const tooltip = tooltipRef.current

    if (!displayed || !hoverable || !tooltip) {
      return
    }

    const instance = createPopper(hoverable, tooltip, {
      placement: placement,
      modifiers: [
        {
          name: 'offset',
          options: {
            offset: [0, 8],
          },
        },
        {
          name: 'flip',
          options: {
            padding: 10,
          },
        },
        {
          name: 'arrow',
          enabled: arrow,
          options: {
            element: arrowRef.current,
            padding: 10,
          },
        },
        {
          name: 'flipArrow',
          enabled: arrow,
          phase: 'write',
          fn({ state }) {
            const [side] = state.placement.split('-')

            setArrowDirection(oppositeSide[side] ?? 'top')
          },
        },
        maxSize,
        applyMaxSize,
      ],
    })

    // Popper's first update is async, so position now - otherwise the enter
    // animation opens on an unpositioned frame, before data-popper-placement
    // has picked its direction.
    instance.forceUpdate()

    return () => instance.destroy()
  }, [arrow, displayed, placement])

  // Only listen while open, so a page full of tooltips doesn't hold a document
  // listener each for as long as it lives
  useEffect(() => {
    if (!isOpen) {
      return
    }

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === Keys.Escape) {
        close()
      }
    }

    document.addEventListener('keydown', onKeyDown)

    return () => document.removeEventListener('keydown', onKeyDown)
  }, [close, isOpen])

  if (title.length === 0) {
    return children as JSX.Element
  }

  return (
    <>
      <div
        className={clsx(interactive?.disabled ? 'pointer-events-none' : '')}
        onBlur={close}
        onFocus={open}
        onMouseEnter={open}
        onMouseLeave={close}
        ref={hoverableRef}
      >
        {/**
         * Attach the aria-describedBy to child element so it can be
         * associated to the accessible label and read out by screen
         * readers.
         * Proper tooltip structure should have multiple children,
         * but if that occurs, each child would have the same association
         * which is not a violation.
         */}
        {Children.map(children, (child, i) => {
          if (isValidElement(child) && i === 0) {
            return cloneElement(child as ReactElement, {
              'aria-describedby': id,
            })
          }

          return child
        })}
      </div>
      {isTouch ? null : (
        <div
          className={clsx(
            'coconut-tooltip px-2.5 py-2 rounded text-white-100 bg-dark-grey-main z-50',
            displayed ? null : 'hidden',
          )}
          data-entering={(displayed && entering) || undefined}
          data-exiting={(displayed && !entering) || undefined}
          id={id}
          onBlur={close}
          onFocus={open}
          onMouseOut={close}
          onMouseOver={open}
          ref={tooltipRef}
          role="tooltip"
        >
          <div className="max-w-xs font-sans text-sm leading-tight">
            {title}
          </div>
          {arrow ? (
            <div
              className={clsx(
                'border-6 border-dark-grey-main w-0 h-0',
                styles.class[arrowDirection],
              )}
              ref={arrowRef}
              style={styles.style[arrowDirection]}
            />
          ) : null}
        </div>
      )}
    </>
  )
}

export default Tooltip
